// Prototype Viewer: Project Configuration
// Managed by /add-to-viewer. Do not edit manually unless you are the project lead.
// Values are derived from project.config.js and prototype intent.md frontmatter.

window.VIEWER_CONFIG = {

  project:     "Zimmermann (website redesign, handover)",
  description: "Reimagined Zimmermann's digital retail experience, making it easier for customers to discover, explore and purchase collections online.",
  theme:       "light",

  client: {
    name:       "Zimmermann",
    background: "#ffffff",
  },

  // access.password has moved to project.config.js - set it there to gate
  // both the viewer and the component catalog with one password.

  // Populated automatically by /add-to-viewer.
  // Each entry corresponds to a prototype folder under /prototypes.
  // Do not add or remove entries manually, run /add-to-viewer instead.
  variants: [

    {
      folder: "templates/main",
      date: "2026-07-15",
      label: "Main page template",
      description: "Full-page shell demonstrating responsive reflow: navigation, logo masthead, and page regions from 1440px down through tablet and mobile.",
      type: "web",
      showCode: false,
    },

    {
      folder: "templates/product-listing",
      date: "2026-07-17",
      label: "Product Listing",
      description: "Full product listing page built on the main shell: category toolbar, 4-column card grid with editorial showcase break, video and recently-viewed placeholder blocks before the footer. Wired in Claude, measurements not confirmed from Figma.",
      type: "web",
      showCode: false,
    },

    {
      folder: "templates/product-detail",
      date: "2026-07-17",
      label: "Product Detail",
      description: "Full product detail page: two-column product detail section, 'More like this' 3-card row, product showcase block, and recently viewed — built on the main shell. Wired in Claude, measurements not confirmed from Figma.",
      type: "web",
      showCode: false,
    },

  ],

};

